typedef float rational_t;

class vector3d
{
public:
  float x, y, z;
  vector3d() {}
  vector3d &operator=(const vector3d &o)
  {
    x = o.x;
    y = o.y;
    z = o.z;
    return *this;
  }
  vector3d operator-(const vector3d &o) const
  {
    vector3d r;
    r.x = x - o.x;
    r.y = y - o.y;
    r.z = z - o.z;
    return r;
  }
  void normalize();
};

class po;
class collision_geometry;

class entity
{
public:
  rational_t get_radius() const;
  const vector3d &get_abs_position() const;
  const po &get_abs_po() const;
  collision_geometry *get_colgeom() const;
};

extern bool collide_segment_sphere(
  const vector3d &, const vector3d &, const vector3d &,
  rational_t, vector3d *);
extern bool collide_segment_geometry(
  const vector3d &, const vector3d &, collision_geometry *,
  vector3d &, vector3d &, const po &, bool);

bool collide_segment_entity(
  const vector3d &p0, const vector3d &p1, const entity *ent,
  vector3d *impact_pos, vector3d *impact_normal,
  rational_t default_radius, bool rear_cull)
{
  rational_t erad;
  erad = ent->get_radius();
  if (erad <= 0.0f)
    erad = default_radius;
  if (erad > 0.0f)
  {
    vector3d sphere_hit_pos;
    bool hit_sphere = collide_segment_sphere(
      p0, p1, ent->get_abs_position(), erad, &sphere_hit_pos);

    if (hit_sphere)
    {
      collision_geometry *cg = ent->get_colgeom();
      if (cg)
      {
        bool hit = collide_segment_geometry(
          p0, p1, cg, *impact_pos, *impact_normal,
          ent->get_abs_po(), rear_cull);
        return hit;
      }
      else
      {
        *impact_pos = sphere_hit_pos;
        *impact_normal = p0 - sphere_hit_pos;
        impact_normal->normalize();
        return true;
      }
    }
  }
  else if (ent->get_colgeom())
  {
    bool hit = collide_segment_geometry(
      p0, p1, ent->get_colgeom(), *impact_pos, *impact_normal,
      ent->get_abs_po(), rear_cull);
    return hit;
  }
  return false;
}
